import * as React from "react";
import type { DataTableTanStackTable as TanStackTable } from "./tanstack-v9";
import {
  IconAdjustmentsHorizontal,
  IconLayoutGrid,
  IconList,
  IconSearch,
  IconX,
} from "../icons";
import type {
  DataTableColumnFilterType,
  DataTableColumnFixed,
  DataTableColumnVisibilityOption,
  DataTableDensity,
  DataTableLabels,
  DataTableSavedView,
  DataTableSelectionAction,
  DataTableToolbarAction,
  DataTableToolbarVisibility,
  DataTableViewMode,
} from "../types";
import type { DataTableUiKit } from "../ui-kit";
import { DATA_TABLE_DEFAULT_LABELS } from "./data-table-labels";

const LazyToolbarDataOperations = React.lazy(
  () => import("./data-table-toolbar-operations"),
);

export type DataTableToolbarColumnFilter = {
  id: string;
  label: string;
  type: DataTableColumnFilterType;
  value: unknown;
  placeholder?: string;
  options: Array<{ label: string; value: string; count?: number; disabled?: boolean }>;
  searchable?: boolean;
  searchPlaceholder?: string;
  trueLabel?: string;
  falseLabel?: string;
  min?: number | string;
  max?: number | string;
  step?: number;
};

type DataTableToolbarProps<TData> = {
  title?: string;
  titleId?: string;
  description?: string;
  descriptionId?: string;
  toolbarQueryValue: string;
  toolbarQueryPlaceholder: string;
  onToolbarQueryValueChange: (value: string) => void;
  customToolbar?: React.ReactNode;
  compactToolbar?: React.ReactNode;
  viewMode: DataTableViewMode;
  onViewModeChange?: (viewMode: DataTableViewMode) => void;
  enableViewToggle: boolean;
  toolbarActions: Array<DataTableToolbarAction<TData>>;
  selectionActions: Array<DataTableSelectionAction<TData>>;
  selectedRows: Array<TData>;
  selectedRowIds: Array<string>;
  showHiddenRows: boolean;
  hiddenRowsLabel?: string;
  onShowHiddenRowsChange?: (showHiddenRows: boolean) => void;
  allRows: Array<TData>;
  columnVisibilityOptions: Array<DataTableColumnVisibilityOption>;
  onColumnVisibilityChange?: (columnId: string, visible: boolean) => void;
  enableColumnPinning: boolean;
  onColumnPinningChange: (columnId: string, side: DataTableColumnFixed | false) => void;
  columnFilters: Array<DataTableToolbarColumnFilter>;
  onColumnFilterChange: (columnId: string, value: unknown) => void;
  onClearColumnFilters: () => void;
  density: DataTableDensity;
  onDensityChange: (density: DataTableDensity) => void;
  enableDensityToggle: boolean;
  labels: Required<DataTableLabels>;
  toolbarVisibility?: DataTableToolbarVisibility;
  openFileDialog?: () => void;
  enableGrouping: boolean;
  enableToolbarColumnChooser: boolean;
  enableToolbarFilterChips: boolean;
  enableToolbarResetLayout: boolean;
  enableToolbarSavedViews: boolean;
  savedViews: Array<DataTableSavedView>;
  onResetColumnLayout: () => void;
  onCreateSavedView: (name: string) => DataTableSavedView | undefined;
  onApplySavedView: (id: string) => boolean;
  onRenameSavedView: (id: string, name: string) => DataTableSavedView | undefined;
  onDeleteSavedView: (id: string) => boolean;
  reorderColumn: (sourceColumnId: string, targetColumnId: string) => void;
  table: TanStackTable<TData>;
};

export function createDataTableToolbar(ui: DataTableUiKit) {
  const uiClassNames = ui.classNames ?? {};
  const {
    Button,
    ButtonGroup,
    DropdownMenu,
    DropdownMenuCheckboxItem,
    DropdownMenuContent,
    DropdownMenuGroup,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
    InputGroup,
    InputGroupAddon,
    InputGroupInput,
    Tooltip,
    TooltipContent,
    TooltipTrigger,
  } = ui;

  return function DataTableToolbar<TData>({
    title,
    titleId,
    description,
    descriptionId,
    toolbarQueryValue,
    toolbarQueryPlaceholder,
    onToolbarQueryValueChange,
    customToolbar,
    compactToolbar,
    viewMode,
    onViewModeChange,
    enableViewToggle,
    toolbarActions,
    selectionActions,
    selectedRows,
    selectedRowIds,
    showHiddenRows,
    hiddenRowsLabel,
    onShowHiddenRowsChange,
    allRows,
    columnVisibilityOptions,
    onColumnVisibilityChange,
    enableColumnPinning,
    onColumnPinningChange,
    columnFilters,
    onColumnFilterChange,
    onClearColumnFilters,
    density,
    onDensityChange,
    enableDensityToggle,
    labels,
    toolbarVisibility,
    openFileDialog,
    enableGrouping,
    enableToolbarColumnChooser,
    enableToolbarFilterChips,
    enableToolbarResetLayout,
    enableToolbarSavedViews,
    savedViews,
    onResetColumnLayout,
    onCreateSavedView,
    onApplySavedView,
    onRenameSavedView,
    onDeleteSavedView,
    reorderColumn,
    table,
  }: DataTableToolbarProps<TData>) {
    const compactSearchInputRef = React.useRef<HTMLInputElement | null>(null);
    const [isCompactSearchVisible, setIsCompactSearchVisible] =
      React.useState(false);
    const compactToolbarIconButtonClassName =
      uiClassNames.toolbarCompactIconButton ?? "";
    const primaryActions = toolbarActions.filter(
      (action) => (action.placement ?? "primary") === "primary",
    );
    const trailingActions = toolbarActions.filter(
      (action) => action.placement === "trailing",
    );
    const showTitle = toolbarVisibility?.title ?? true;
    const showSearch = toolbarVisibility?.search ?? true;
    const showActions = toolbarVisibility?.actions ?? true;
    const showTrailingActions = toolbarVisibility?.trailingActions ?? true;
    const showOptions = toolbarVisibility?.options ?? true;
    const showViewToggle = toolbarVisibility?.viewToggle ?? true;
    const showCustomToolbar = toolbarVisibility?.customToolbar ?? true;
    const hasVisibleTitle = showTitle && Boolean(title || description);
    const hasVisibleSearch = showSearch;
    const hasVisiblePrimaryActions = showActions && primaryActions.length > 0;
    const hasVisibleSelectionActions =
      selectedRowIds.length > 0 && selectionActions.length > 0;
    const hasVisibleOptions =
      showOptions &&
      (columnVisibilityOptions.some((column) => column.canHide) ||
        Boolean(onShowHiddenRowsChange && hiddenRowsLabel) ||
        enableColumnPinning ||
        enableDensityToggle ||
        enableGrouping ||
        enableToolbarColumnChooser ||
        enableToolbarResetLayout ||
        enableToolbarSavedViews);
    const hasToolbarOperationsMenu =
      enableToolbarColumnChooser ||
      enableToolbarResetLayout ||
      enableToolbarSavedViews;
    const activeColumnFilters = columnFilters.filter((filter) =>
      hasColumnFilterValue(filter.value),
    );
    const toolbarOperationsUi = {
      Button,
      DropdownMenuCheckboxItem,
      DropdownMenuGroup,
      DropdownMenuItem,
      DropdownMenuLabel,
      DropdownMenuSeparator,
      InputGroup,
      InputGroupAddon,
      InputGroupInput,
    };
    const renderToolbarDataOperations = (placement: "menu" | "chips") => (
      <React.Suspense fallback={null}>
        <LazyToolbarDataOperations
          placement={placement}
          ui={toolbarOperationsUi}
          labels={labels}
          enableColumnChooser={enableToolbarColumnChooser}
          enableFilterChips={enableToolbarFilterChips}
          enableResetLayout={enableToolbarResetLayout}
          enableSavedViews={enableToolbarSavedViews}
          enableColumnPinning={enableColumnPinning}
          columnVisibilityOptions={columnVisibilityOptions}
          onColumnVisibilityChange={onColumnVisibilityChange}
          onColumnPinningChange={onColumnPinningChange}
          reorderColumn={reorderColumn}
          table={table as unknown as TanStackTable<unknown>}
          onResetColumnLayout={onResetColumnLayout}
          savedViews={savedViews}
          onCreateSavedView={onCreateSavedView}
          onApplySavedView={onApplySavedView}
          onRenameSavedView={onRenameSavedView}
          onDeleteSavedView={onDeleteSavedView}
          toolbarQueryValue={toolbarQueryValue}
          onToolbarQueryValueChange={onToolbarQueryValueChange}
          activeColumnFilters={activeColumnFilters}
          onColumnFilterChange={onColumnFilterChange}
          onClearColumnFilters={onClearColumnFilters}
        />
      </React.Suspense>
    );
    const groupableColumns = table
      .getAllLeafColumns()
      .filter(
        (column) =>
          !column.id.startsWith("__") &&
          column.getCanGroup(),
      );
    const groupedColumns = table.store.state.grouping.flatMap((id) => {
      const column = table.getColumn(id);
      return column ? [column] : [];
    });
    const hasVisibleViewToggle =
      showViewToggle && enableViewToggle && Boolean(onViewModeChange);
    const hasVisibleTrailingActions =
      showTrailingActions && trailingActions.length > 0;
    const hasVisibleCustomToolbar = showCustomToolbar && Boolean(customToolbar);
    const hasVisibleCompactToolbar =
      showCustomToolbar && Boolean(compactToolbar ?? customToolbar);
    const selectedRowCountLabel = labels.selectedRows(selectedRowIds.length);

    React.useEffect(() => {
      if (!isCompactSearchVisible) {
        return;
      }

      compactSearchInputRef.current?.focus();
    }, [isCompactSearchVisible]);

    if (
      !hasVisibleTitle &&
      !hasVisibleSearch &&
      !hasVisiblePrimaryActions &&
      !hasVisibleSelectionActions &&
      !hasVisibleOptions &&
      !hasVisibleViewToggle &&
      !hasVisibleTrailingActions &&
      !hasVisibleCustomToolbar &&
      !hasVisibleCompactToolbar
    ) {
      return null;
    }

    return (
      <div className="flex flex-col gap-4 pb-0">
        {showTitle && (title || description) ? (
          <div className="flex flex-col gap-1">
            {title ? (
              <h2
                id={titleId}
                className="text-lg font-semibold tracking-tight"
              >
                {title}
              </h2>
            ) : null}
            {description ? (
              <p
                id={descriptionId}
                className={`max-w-3xl text-sm ${uiClassNames.mutedText ?? "opacity-70"}`}
              >
                {description}
              </p>
            ) : null}
          </div>
        ) : null}

        <div className="flex flex-col gap-3">
          <div
            data-dtp-slot="data-table-toolbar-controls"
            className="flex items-center gap-2 overflow-x-auto px-1 @min-[768px]/data-table:gap-3 @min-[768px]/data-table:overflow-visible"
          >
            {showSearch ? (
              <>
                <div className="hidden min-w-0 grow max-w-md @min-[768px]/data-table:block">
                  <InputGroup className="min-w-0">
                    <InputGroupInput
                      value={toolbarQueryValue}
                      onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                        onToolbarQueryValueChange(event.target.value);
                      }}
                      placeholder={toolbarQueryPlaceholder}
                    />
                    <InputGroupAddon align="inline-start" aria-hidden="true">
                      <IconSearch />
                    </InputGroupAddon>
                    {toolbarQueryValue ? (
                      <InputGroupAddon align="inline-end">
                        <button
                          type="button"
                          className={`inline-flex size-5 items-center justify-center rounded-md transition-colors focus-visible:outline-none ${uiClassNames.toolbarIconButton ?? "opacity-70 hover:opacity-100"}`}
                          onClick={() => {
                            onToolbarQueryValueChange("");
                          }}
                          aria-label={labels.clearSearch}
                          title={labels.clearSearch}
                        >
                          <IconX />
                        </button>
                      </InputGroupAddon>
                    ) : null}
                  </InputGroup>
                </div>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      type="button"
                      variant={
                        isCompactSearchVisible || toolbarQueryValue
                          ? "secondary"
                          : "outline"
                      }
                      size="icon-sm"
                      aria-label={labels.searchTable}
                      aria-pressed={isCompactSearchVisible}
                      className={`shrink-0 @min-[768px]/data-table:hidden ${compactToolbarIconButtonClassName} ${uiClassNames.toolbarInputButton ?? ""}`}
                      onClick={() => {
                        setIsCompactSearchVisible((current) => !current);
                      }}
                    >
                      <IconSearch />
                      <span className="sr-only">{labels.searchTable}</span>
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>{labels.searchTable}</TooltipContent>
                </Tooltip>
              </>
            ) : null}

            {showActions ? (
              <div className="flex shrink-0 items-center gap-2">
                {primaryActions.map((action) => {
                  const collapsesToIcon =
                    !action.iconOnly && Boolean(action.icon);
                  const button = (
                    <Button
                      key={action.key}
                      type="button"
                      className={
                        collapsesToIcon
                          ? `size-7 shrink-0 px-0 @min-[768px]/data-table:h-8 @min-[768px]/data-table:w-fit @min-[768px]/data-table:px-2.5 ${compactToolbarIconButtonClassName}`
                          : action.iconOnly
                            ? `size-7 shrink-0 @min-[768px]/data-table:size-8 ${compactToolbarIconButtonClassName}`
                            : "size-7 shrink-0 @min-[768px]/data-table:h-8 @min-[768px]/data-table:w-fit"
                      }
                      variant={action.variant ?? "outline"}
                      size={action.iconOnly ? "icon" : "default"}
                      onClick={() => {
                        void action.onClick({
                          rows: allRows,
                          openFileDialog,
                        });
                      }}
                      disabled={action.disabled}
                      aria-label={action.label}
                      title={action.iconOnly ? undefined : action.label}
                    >
                      {action.icon ? <action.icon /> : null}
                      {action.iconOnly ? (
                        <span className="sr-only">{action.label}</span>
                      ) : collapsesToIcon ? (
                        <span className="hidden @min-[768px]/data-table:inline">
                          {action.label}
                        </span>
                      ) : (
                        <span>{action.label}</span>
                      )}
                    </Button>
                  );

                  return action.iconOnly ? (
                    <Tooltip key={action.key}>
                      <TooltipTrigger asChild>{button}</TooltipTrigger>
                      <TooltipContent>{action.label}</TooltipContent>
                    </Tooltip>
                  ) : (
                    button
                  );
                })}
              </div>
            ) : null}

            {hasVisibleCompactToolbar ? (
              <div
                data-dtp-slot="data-table-toolbar-compact-custom"
                className="flex shrink-0 items-center gap-2 @min-[1024px]/data-table:hidden"
              >
                {compactToolbar ?? customToolbar}
              </div>
            ) : null}

            <div className="grow" aria-hidden="true" />

            <div
              data-dtp-slot="data-table-toolbar-end-controls"
              className="flex shrink-0 items-center gap-2"
            >
              {selectedRowIds.length ? (
                <div
                  className={`hidden text-sm @min-[768px]/data-table:block ${uiClassNames.mutedText ?? "opacity-70"}`}
                >
                  {selectedRowCountLabel}
                </div>
              ) : null}
              {selectedRowIds.length
                ? selectionActions.map((action) => {
                    const Icon = action.icon;
                    const context = {
                      rows: selectedRows,
                      rowIds: selectedRowIds,
                    };
                    const disabled =
                      typeof action.disabled === "function"
                        ? action.disabled(selectedRows, context)
                        : action.disabled;

                    return (
                      <Tooltip key={action.key}>
                        <TooltipTrigger asChild>
                          <Button
                            type="button"
                            variant={action.variant ?? "secondary"}
                            size="icon-sm"
                            className={compactToolbarIconButtonClassName}
                            disabled={disabled}
                            onClick={() => {
                              void action.onClick(context);
                            }}
                            aria-label={action.label}
                          >
                            {Icon ? <Icon /> : null}
                            <span className="sr-only">{action.label}</span>
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>{action.label}</TooltipContent>
                      </Tooltip>
                    );
                  })
                : null}

              {hasVisibleOptions ? (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button
                      type="button"
                      variant="outline"
                      size="icon-sm"
                      aria-label={labels.tableOptions}
                      className={`${compactToolbarIconButtonClassName} ${uiClassNames.toolbarInputButton ?? ""}`}
                      title={labels.tableOptions}
                    >
                      <IconAdjustmentsHorizontal />
                      <span className="sr-only">{labels.tableOptions}</span>
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-56">
                    <DropdownMenuLabel>{labels.tableOptions}</DropdownMenuLabel>
                    <DropdownMenuGroup>
                      {onShowHiddenRowsChange && hiddenRowsLabel ? (
                        <DropdownMenuCheckboxItem
                          checked={showHiddenRows}
                          onCheckedChange={(
                            checked: boolean | "indeterminate",
                          ) => {
                            onShowHiddenRowsChange(checked === true);
                          }}
                        >
                          {labels.showHiddenRows(hiddenRowsLabel)}
                        </DropdownMenuCheckboxItem>
                      ) : null}
                    </DropdownMenuGroup>
                    {enableDensityToggle ? (
                      <>
                        <DropdownMenuSeparator />
                        <DropdownMenuLabel>{labels.density}</DropdownMenuLabel>
                        <DropdownMenuGroup>
                          {(
                            [
                              ["compact", labels.compactDensity],
                              ["comfortable", labels.comfortableDensity],
                              ["spacious", labels.spaciousDensity],
                            ] as const
                          ).map(([nextDensity, label]) => (
                            <DropdownMenuCheckboxItem
                              key={nextDensity}
                              checked={density === nextDensity}
                              onCheckedChange={() => {
                                onDensityChange(nextDensity);
                              }}
                            >
                              {label}
                            </DropdownMenuCheckboxItem>
                          ))}
                        </DropdownMenuGroup>
                      </>
                    ) : null}
                    {hasToolbarOperationsMenu
                      ? renderToolbarDataOperations("menu")
                      : null}
                    {!enableToolbarColumnChooser &&
                    columnVisibilityOptions.some((column) => column.canHide) ? (
                      <>
                        <DropdownMenuSeparator />
                        <DropdownMenuLabel>{labels.columns}</DropdownMenuLabel>
                        <DropdownMenuGroup>
                          {columnVisibilityOptions
                            .filter((column) => column.canHide)
                            .map((column) => (
                              <DropdownMenuCheckboxItem
                                key={column.id}
                                checked={column.visible}
                                onCheckedChange={(
                                  checked: boolean | "indeterminate",
                                ) => {
                                  onColumnVisibilityChange?.(
                                    column.id,
                                    checked === true,
                                  );
                                }}
                              >
                                {column.label}
                              </DropdownMenuCheckboxItem>
                            ))}
                        </DropdownMenuGroup>
                      </>
                    ) : null}
                    {enableColumnPinning && !enableToolbarColumnChooser ? (
                      <>
                        <DropdownMenuSeparator />
                        <DropdownMenuLabel>
                          {labels.pinLeft} / {labels.pinRight}
                        </DropdownMenuLabel>
                        <DropdownMenuGroup>
                          {columnVisibilityOptions.map((column) => (
                            <DropdownMenuItem
                              key={`pin-${column.id}`}
                              onSelect={(event: Event) => {
                                event.preventDefault();
                              }}
                            >
                              <span className="min-w-0 flex-1 truncate">
                                {column.label}
                              </span>
                              <button
                                type="button"
                                className="px-1 text-xs"
                                aria-label={`${labels.pinLeft}: ${column.label}`}
                                onClick={(event) => {
                                  event.stopPropagation();
                                  onColumnPinningChange(column.id, "left");
                                }}
                              >
                                L
                              </button>
                              <button
                                type="button"
                                className="px-1 text-xs"
                                aria-label={`${labels.pinRight}: ${column.label}`}
                                onClick={(event) => {
                                  event.stopPropagation();
                                  onColumnPinningChange(column.id, "right");
                                }}
                              >
                                R
                              </button>
                              <button
                                type="button"
                                className="px-1 text-xs"
                                aria-label={`${labels.unpin}: ${column.label}`}
                                onClick={(event) => {
                                  event.stopPropagation();
                                  onColumnPinningChange(column.id, false);
                                }}
                              >
                                -
                              </button>
                            </DropdownMenuItem>
                          ))}
                        </DropdownMenuGroup>
                      </>
                    ) : null}
                    {enableGrouping && groupableColumns.length ? (
                      <>
                        <DropdownMenuSeparator />
                        <DropdownMenuLabel>{labels.grouping}</DropdownMenuLabel>
                        <DropdownMenuGroup>
                          {groupableColumns.map((column) => {
                            const columnLabel =
                              typeof column.columnDef.header === "string"
                                ? column.columnDef.header
                                : column.id;
                            const isGrouped = column.getIsGrouped();
                            return (
                              <DropdownMenuCheckboxItem
                                key={`group-${column.id}`}
                                checked={isGrouped}
                                onCheckedChange={() => {
                                  column.toggleGrouping();
                                }}
                              >
                                {isGrouped
                                  ? labels.ungroup(columnLabel)
                                  : labels.groupBy(columnLabel)}
                              </DropdownMenuCheckboxItem>
                            );
                          })}
                        </DropdownMenuGroup>
                      </>
                    ) : null}
                  </DropdownMenuContent>
                </DropdownMenu>
              ) : null}

              {showViewToggle && enableViewToggle && onViewModeChange ? (
                <ButtonGroup>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        type="button"
                        variant={viewMode === "table" ? "default" : "outline"}
                        aria-pressed={viewMode === "table"}
                        className={
                          viewMode === "table"
                            ? compactToolbarIconButtonClassName
                            : `${compactToolbarIconButtonClassName} ${uiClassNames.toolbarInputButton ?? ""}`
                        }
                        size="icon-sm"
                        onClick={() => {
                          onViewModeChange("table");
                        }}
                      >
                        <IconList />
                        <span className="sr-only">
                          {labels.switchToTableView ??
                            DATA_TABLE_DEFAULT_LABELS.switchToTableView}
                        </span>
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>
                      {labels.tableView ??
                        DATA_TABLE_DEFAULT_LABELS.tableView}
                    </TooltipContent>
                  </Tooltip>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        type="button"
                        variant={viewMode === "card" ? "default" : "outline"}
                        aria-pressed={viewMode === "card"}
                        className={
                          viewMode === "table"
                            ? `${compactToolbarIconButtonClassName} ${uiClassNames.toolbarInputButton ?? ""}`
                            : compactToolbarIconButtonClassName
                        }
                        size="icon-sm"
                        onClick={() => {
                          onViewModeChange("card");
                        }}
                      >
                        <IconLayoutGrid />
                        <span className="sr-only">
                          {labels.switchToCardView ??
                            DATA_TABLE_DEFAULT_LABELS.switchToCardView}
                        </span>
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>
                      {labels.cardView ??
                        DATA_TABLE_DEFAULT_LABELS.cardView}
                    </TooltipContent>
                  </Tooltip>
                </ButtonGroup>
              ) : null}

              {showTrailingActions
                ? trailingActions.map((action) => {
                    const collapsesToIcon =
                      !action.iconOnly && Boolean(action.icon);
                    const button = (
                      <Button
                        key={action.key}
                        type="button"
                        variant={action.variant ?? "outline"}
                        size={action.iconOnly ? "icon-sm" : "default"}
                        onClick={() => {
                          void action.onClick({
                            rows: allRows,
                            openFileDialog,
                          });
                        }}
                        disabled={action.disabled}
                        aria-label={action.label}
                        title={action.iconOnly ? undefined : action.label}
                        className={`size-7 shrink-0 ${action.iconOnly ? "" : `${collapsesToIcon ? "px-0 @min-[768px]/data-table:px-2.5" : ""} @min-[768px]/data-table:h-8 @min-[768px]/data-table:w-fit`} ${action.iconOnly || collapsesToIcon ? compactToolbarIconButtonClassName : ""} ${uiClassNames.toolbarInputButton ?? ""}`}
                      >
                        {action.icon ? (
                          <action.icon
                            data-icon={
                              action.iconOnly ? undefined : "inline-start"
                            }
                          />
                        ) : null}
                        {action.iconOnly ? (
                          <span className="sr-only">{action.label}</span>
                        ) : collapsesToIcon ? (
                          <span className="hidden @min-[768px]/data-table:inline">
                            {action.label}
                          </span>
                        ) : (
                          <span>{action.label}</span>
                        )}
                      </Button>
                    );

                    return action.iconOnly ? (
                      <Tooltip key={action.key}>
                        <TooltipTrigger asChild>{button}</TooltipTrigger>
                        <TooltipContent>{action.label}</TooltipContent>
                      </Tooltip>
                    ) : (
                      button
                    );
                  })
                : null}
            </div>
          </div>

          {showSearch && isCompactSearchVisible ? (
            <div
              data-dtp-slot="data-table-toolbar-compact-search"
              className="min-w-0 @min-[768px]/data-table:hidden"
            >
              <InputGroup>
                <InputGroupInput
                  ref={compactSearchInputRef}
                  value={toolbarQueryValue}
                  onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                    onToolbarQueryValueChange(event.target.value);
                  }}
                  placeholder={toolbarQueryPlaceholder}
                />
                <InputGroupAddon align="inline-start" aria-hidden="true">
                  <IconSearch />
                </InputGroupAddon>
                {toolbarQueryValue ? (
                  <InputGroupAddon align="inline-end">
                    <button
                      type="button"
                      className={`inline-flex size-5 items-center justify-center rounded-md transition-colors focus-visible:outline-none ${uiClassNames.toolbarIconButton ?? "opacity-70 hover:opacity-100"}`}
                      onClick={() => {
                        onToolbarQueryValueChange("");
                      }}
                      aria-label={labels.clearSearch}
                      title={labels.clearSearch}
                    >
                      <IconX />
                    </button>
                  </InputGroupAddon>
                ) : null}
              </InputGroup>
            </div>
          ) : null}

          {columnFilters.length ? (
            <div
              data-dtp-slot="data-table-toolbar-filters"
              className="flex min-w-0 flex-wrap items-center gap-2"
            >
              {columnFilters.map((filter) => (
                <ToolbarColumnFilterControl
                  key={filter.id}
                  filter={filter}
                  labels={labels}
                  onColumnFilterChange={onColumnFilterChange}
                />
              ))}
              {columnFilters.some((filter) =>
                hasColumnFilterValue(filter.value),
              ) ? (
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={onClearColumnFilters}
                >
                  {labels.clearFilters}
                </Button>
              ) : null}
            </div>
          ) : null}

          {enableToolbarFilterChips
            ? renderToolbarDataOperations("chips")
            : null}

          {enableGrouping && groupedColumns.length ? (
            <div
              data-dtp-slot="data-table-grouping-bar"
              aria-label={labels.grouping}
              className="flex flex-wrap items-center gap-2"
            >
              <span className="text-sm opacity-70">{labels.grouping}:</span>
              {groupedColumns.map((column, groupingIndex) => {
                const columnLabel =
                  typeof column.columnDef.header === "string"
                    ? column.columnDef.header
                    : column.id;
                const moveGrouping = (nextIndex: number) => {
                  const nextGrouping = [...table.store.state.grouping];
                  const [groupingId] = nextGrouping.splice(groupingIndex, 1);
                  if (groupingId === undefined) return;
                  nextGrouping.splice(nextIndex, 0, groupingId);
                  table.setGrouping(nextGrouping);
                };
                return (
                  <div
                    key={`grouping-bar-${column.id}`}
                    className="inline-flex items-center rounded-md border"
                  >
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      disabled={groupingIndex === 0}
                      onClick={() => moveGrouping(groupingIndex - 1)}
                      aria-label={labels.moveGroupingEarlier(columnLabel)}
                    >
                      <span aria-hidden="true">←</span>
                    </Button>
                    <Button
                      type="button"
                      variant="secondary"
                      size="sm"
                      onClick={() => column.toggleGrouping()}
                      aria-label={labels.removeGrouping(columnLabel)}
                    >
                      {columnLabel} <span aria-hidden="true">×</span>
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      disabled={groupingIndex === groupedColumns.length - 1}
                      onClick={() => moveGrouping(groupingIndex + 1)}
                      aria-label={labels.moveGroupingLater(columnLabel)}
                    >
                      <span aria-hidden="true">→</span>
                    </Button>
                  </div>
                );
              })}
            </div>
          ) : null}

        </div>

        {showCustomToolbar && customToolbar ? (
          <div
            data-dtp-slot="data-table-toolbar-desktop-custom"
            className="hidden flex-row items-center gap-3 @min-[1024px]/data-table:flex"
          >
            {customToolbar}
          </div>
        ) : null}
      </div>
    );
  };

  function ToolbarColumnFilterControl({
    filter,
    labels,
    onColumnFilterChange,
  }: {
    filter: DataTableToolbarColumnFilter;
    labels: Required<DataTableLabels>;
    onColumnFilterChange: (columnId: string, value: unknown) => void;
  }) {
    const [facetQuery, setFacetQuery] = React.useState("");
    if (filter.type === "text") {
      return (
        <InputGroup className="min-w-48 max-w-64">
          <InputGroupInput
            value={typeof filter.value === "string" ? filter.value : ""}
            onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
              onColumnFilterChange(filter.id, event.target.value);
            }}
            placeholder={filter.placeholder ?? filter.label}
            aria-label={`${labels.filters}: ${filter.label}`}
          />
          <InputGroupAddon align="inline-start" aria-hidden="true">
            <IconSearch />
          </InputGroupAddon>
        </InputGroup>
      );
    }

    if (filter.type === "numberRange" || filter.type === "dateRange") {
      const range = normalizeToolbarRangeValue(filter.value);
      const inputType = filter.type === "numberRange" ? "number" : "date";
      const fromLabel =
        labels.filterFrom ?? DATA_TABLE_DEFAULT_LABELS.filterFrom;
      const toLabel = labels.filterTo ?? DATA_TABLE_DEFAULT_LABELS.filterTo;

      return (
        <div
          role="group"
          aria-label={`${labels.filters}: ${filter.label}`}
          className="flex min-w-0 items-center gap-1.5"
        >
          <InputGroup className="min-w-32 max-w-44">
            <InputGroupInput
              type={inputType}
              inputMode={inputType === "number" ? "decimal" : undefined}
              value={range.from ?? ""}
              min={filter.min}
              max={filter.max}
              step={inputType === "number" ? filter.step : undefined}
              onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                onColumnFilterChange(filter.id, {
                  ...range,
                  from: parseRangeInputValue(event.target.value, inputType),
                });
              }}
              aria-label={`${filter.label}: ${fromLabel}`}
            />
            <InputGroupAddon align="inline-start">{fromLabel}</InputGroupAddon>
          </InputGroup>
          <InputGroup className="min-w-32 max-w-44">
            <InputGroupInput
              type={inputType}
              inputMode={inputType === "number" ? "decimal" : undefined}
              value={range.to ?? ""}
              min={filter.min}
              max={filter.max}
              step={inputType === "number" ? filter.step : undefined}
              onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                onColumnFilterChange(filter.id, {
                  ...range,
                  to: parseRangeInputValue(event.target.value, inputType),
                });
              }}
              aria-label={`${filter.label}: ${toLabel}`}
            />
            <InputGroupAddon align="inline-start">{toLabel}</InputGroupAddon>
          </InputGroup>
        </div>
      );
    }

    const isBoolean = filter.type === "boolean";
    const isFaceted = filter.type === "faceted";
    const booleanOptions = [
      {
        label:
          filter.trueLabel ??
          labels.filterTrue ??
          DATA_TABLE_DEFAULT_LABELS.filterTrue,
        value: "true",
      },
      {
        label:
          filter.falseLabel ??
          labels.filterFalse ??
          DATA_TABLE_DEFAULT_LABELS.filterFalse,
        value: "false",
      },
    ];
    const options: DataTableToolbarColumnFilter["options"] = isBoolean
      ? booleanOptions
      : filter.options;
    const visibleOptions =
      isFaceted && facetQuery
        ? options.filter((option) =>
            option.label.toLocaleLowerCase().includes(facetQuery.toLocaleLowerCase()),
          )
        : options;
    const selectedValue =
      typeof filter.value === "string" || typeof filter.value === "boolean"
        ? String(filter.value)
        : "";
    const selectedValues = Array.isArray(filter.value)
      ? filter.value.map(String)
      : selectedValue
        ? [selectedValue]
        : [];
    const selectedLabel =
      selectedValues.length === 0
        ? filter.label
        : `${filter.label}: ${
            selectedValues.length === 1
              ? (options.find(
                  (option) => option.value === String(selectedValues[0]),
                )?.label ?? selectedValues[0])
              : selectedValues.length
          }`;

    return (
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button type="button" variant="outline" size="sm">
            {selectedLabel}
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-56">
          <DropdownMenuLabel>{filter.label}</DropdownMenuLabel>
          {isFaceted && filter.searchable !== false ? (
            <div className="px-2 pb-2">
              <InputGroup>
                <InputGroupInput
                  value={facetQuery}
                  onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                    setFacetQuery(event.target.value);
                  }}
                  placeholder={filter.searchPlaceholder ?? labels.facetSearch(filter.label)}
                  aria-label={labels.facetSearch(filter.label)}
                />
                <InputGroupAddon align="inline-start" aria-hidden="true">
                  <IconSearch />
                </InputGroupAddon>
              </InputGroup>
            </div>
          ) : null}
          <DropdownMenuGroup>
            {filter.type === "select" || isBoolean || isFaceted ? (
              <DropdownMenuItem
                onClick={() => {
                  onColumnFilterChange(filter.id, "");
                }}
              >
                {labels.allFilterOptions ??
                  DATA_TABLE_DEFAULT_LABELS.allFilterOptions}
              </DropdownMenuItem>
            ) : null}
            {visibleOptions.map((option) => (
              <DropdownMenuCheckboxItem
                key={option.value}
                checked={selectedValues.includes(option.value)}
                disabled={option.disabled}
                onCheckedChange={(checked: boolean | "indeterminate") => {
                  if (filter.type === "select" || isBoolean) {
                    onColumnFilterChange(
                      filter.id,
                      checked === true ? option.value : "",
                    );
                    return;
                  }

                  const nextValues = new Set(selectedValues);
                  if (checked === true) {
                    nextValues.add(option.value);
                  } else {
                    nextValues.delete(option.value);
                  }
                  onColumnFilterChange(filter.id, Array.from(nextValues));
                }}
              >
                <span className="min-w-0 flex-1 truncate">{option.label}</span>
                {option.count !== undefined ? (
                  <span className="ml-3 tabular-nums opacity-70">{option.count}</span>
                ) : null}
              </DropdownMenuCheckboxItem>
            ))}
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    );
  }
}

function hasColumnFilterValue(value: unknown) {
  if (Array.isArray(value)) {
    return value.length > 0;
  }

  if (value && typeof value === "object") {
    if ("from" in value || "to" in value) {
      return Object.values(value).some(hasColumnFilterValue);
    }

    return true;
  }

  return value !== undefined && value !== null && value !== "";
}

function normalizeToolbarRangeValue(value: unknown): {
  from?: number | string;
  to?: number | string;
} {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  const range = value as { from?: unknown; to?: unknown };
  return {
    ...(typeof range.from === "number" || typeof range.from === "string"
      ? { from: range.from }
      : {}),
    ...(typeof range.to === "number" || typeof range.to === "string"
      ? { to: range.to }
      : {}),
  };
}

function parseRangeInputValue(value: string, inputType: "number" | "date") {
  if (!value) {
    return undefined;
  }

  return inputType === "number" ? Number(value) : value;
}
